-- A bigger Metric Catalog (GLOSSARY: Metric Catalog): about a hundred common business Metrics in nine categories, each
-- with a one-sentence definition of what is counted and what is not. Add-only and safe to run again: rows are matched
-- by name, so a name that is already in the catalog keeps its row.
--
-- industries and segments say which kinds of business a Metric suits, so suggestions can prefer them later; null means
-- any. Values are lowercase keys: industries saas, ecommerce, retail, manufacturing, logistics, construction,
-- hospitality, professional_services, agency; segments b2b, b2c.

alter table catalog_metrics add column if not exists industries text[];
alter table catalog_metrics add column if not exists segments text[];
create unique index if not exists catalog_metrics_name_key on catalog_metrics (name);

-- "Team" was the only category named after people rather than the work; the new rows join it as People.
update catalog_metrics set category = 'People' where category = 'Team';

-- The catalog's first 13 rows are included unchanged: on a fresh installation this runs before the demo seed, which
-- only fills an empty catalog, so they would otherwise be missing there.
on conflict (name) do nothing;
